export const SHAPES = [
  "circle",
  "square",
  "triangle",
  "diamond",
  "star",
  "hexagon",
  "plus",
  "chevron",
] as const;

export const MARKERS = [
  "top",
  "top-right",
  "right",
  "bottom-right",
  "bottom",
  "bottom-left",
  "left",
  "top-left",
] as const;

export const PALETTE = [
  { name: "cyan", color: "#63E7FF" },
  { name: "magenta", color: "#FF71D6" },
  { name: "green", color: "#8BEA7D" },
  { name: "yellow", color: "#FFE082" },
  { name: "orange", color: "#FFB064" },
  { name: "violet", color: "#B49AFF" },
  { name: "rose", color: "#FF8296" },
  { name: "ice", color: "#D9F3FF" },
] as const;

export interface FaceData {
  readonly id: number;
  readonly shape: (typeof SHAPES)[number];
  readonly marker: (typeof MARKERS)[number];
  readonly fill: "solid" | "outline";
  readonly paletteName: (typeof PALETTE)[number]["name"];
  readonly color: string;
  readonly markerX: number;
  readonly markerY: number;
  readonly accessibleName: string;
}

const MARKER_POINTS: readonly (readonly [number, number])[] = [
  [50, 10],
  [78.284, 21.716],
  [90, 50],
  [78.284, 78.284],
  [50, 90],
  [21.716, 78.284],
  [10, 50],
  [21.716, 21.716],
];

export function getFaceData(id: number): FaceData | null {
  if (!Number.isSafeInteger(id) || id < 0 || id > 127) return null;
  const shape = SHAPES[id % SHAPES.length];
  const markerIndex = Math.floor(id / 8) % MARKERS.length;
  const marker = MARKERS[markerIndex];
  const palette = PALETTE[markerIndex];
  const point = MARKER_POINTS[markerIndex];
  if (shape === undefined || marker === undefined || palette === undefined || point === undefined) {
    return null;
  }
  const fill = id < 64 ? "solid" : "outline";
  return {
    id,
    shape,
    marker,
    fill,
    paletteName: palette.name,
    color: palette.color,
    markerX: point[0],
    markerY: point[1],
    accessibleName: `${palette.name} ${fill} ${shape}, marker ${marker}`,
  };
}
export type ArrowDirection = "ArrowLeft" | "ArrowRight" | "ArrowUp" | "ArrowDown";

export function focusDestination(
  index: number,
  size: number,
  direction: ArrowDirection,
): number {
  const row = Math.floor(index / size);
  const column = index % size;

  if (direction === "ArrowLeft") return column === 0 ? index : index - 1;
  if (direction === "ArrowRight") return column === size - 1 ? index : index + 1;
  if (direction === "ArrowUp") return row === 0 ? index : index - size;
  return row === size - 1 ? index : index + size;
}
import { describe, expect, it } from "vitest";
import { getFaceData } from "./face-data.ts";

describe("face identities", () => {
  it("names the documented solid and outline examples", () => {
    expect(getFaceData(0)?.accessibleName).toBe("cyan solid circle, marker top");
    expect(getFaceData(64)?.accessibleName).toBe("cyan outline circle, marker top");
  });

  it("generates all 128 shape, marker, and fill combinations", () => {
    const faces = Array.from({ length: 128 }, (_, id) => getFaceData(id));
    expect(faces.every((face) => face !== null)).toBe(true);
    expect(new Set(faces.map((face) => face?.accessibleName)).size).toBe(128);
    expect(getFaceData(-1)).toBeNull();
    expect(getFaceData(128)).toBeNull();
  });

  it("places radial marker centers 40 units from the face center", () => {
    for (let id = 0; id < 128; id += 8) {
      const face = getFaceData(id);
      if (face === null) continue;
      expect(Math.hypot(face.markerX - 50, face.markerY - 50)).toBeCloseTo(40, 2);
    }
  });
});
import { describe, expect, it } from "vitest";
import { focusDestination } from "./navigation.ts";

describe("board keyboard navigation", () => {
  it("moves within a row and column", () => {
    expect(focusDestination(5, 4, "ArrowLeft")).toBe(4);
    expect(focusDestination(5, 4, "ArrowRight")).toBe(6);
    expect(focusDestination(5, 4, "ArrowUp")).toBe(1);
    expect(focusDestination(5, 4, "ArrowDown")).toBe(9);
  });

  it("stops at every board edge", () => {
    expect(focusDestination(0, 4, "ArrowLeft")).toBe(0);
    expect(focusDestination(3, 4, "ArrowRight")).toBe(3);
    expect(focusDestination(1, 4, "ArrowUp")).toBe(1);
    expect(focusDestination(13, 4, "ArrowDown")).toBe(13);
  });
});

