import { forwardRef, type KeyboardEvent, type MouseEvent } from "react";
import { SELECTION_KINDS, type GameState } from "../state.ts";
import { Face } from "./Face.tsx";
import { getFaceData } from "./face-data.ts";
import { focusDestination, type ArrowDirection } from "./navigation.ts";
import "./Face.css";
import "./Card.css";

export interface CardProps {
  readonly game: GameState;
  readonly index: number;
  readonly tabStop: boolean;
  readonly paused: boolean;
  readonly onActivate: (index: number) => void;
  readonly onFocusCard: (index: number) => void;
  readonly onMoveFocus: (index: number) => void;
}

function isMatched(game: GameState, index: number): boolean {
  return game.matched.includes(index);
}

function isRevealed(game: GameState, index: number, matched: boolean): boolean {
  if (matched) return true;
  if (game.selection.kind === SELECTION_KINDS.one) return game.selection.index === index;
  return game.selection.kind === SELECTION_KINDS.mismatch &&
    (game.selection.first === index || game.selection.second === index);
}

function handleClick(event: MouseEvent<HTMLButtonElement>, activate: () => void): void {
  if (
    event.button !== 0 ||
    event.altKey || event.ctrlKey || event.metaKey || event.shiftKey
  ) {
    return;
  }
  activate();
}

function isArrowDirection(key: string): key is ArrowDirection {
  return key === "ArrowLeft" || key === "ArrowRight" || key === "ArrowUp" || key === "ArrowDown";
}

function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number, size: number, move: (index: number) => void): void {
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  if (!isArrowDirection(event.key)) return;
  event.preventDefault();
  move(focusDestination(index, size, event.key));
}

export const Card = forwardRef<HTMLButtonElement, CardProps>(function Card({
  game,
  index,
  tabStop,
  paused,
  onActivate,
  onFocusCard,
  onMoveFocus,
}, ref) {
  const size = game.board.size;
  const matched = isMatched(game, index);
  const revealed = isRevealed(game, index, matched);
  const faceId = revealed ? game.board.deck[index] : undefined;
  const face = faceId === undefined ? null : getFaceData(faceId);
  const row = Math.floor(index / size) + 1;
  const column = (index % size) + 1;
  const stateName = matched ? "matched" : revealed ? "revealed" : "closed";
  const position = `Row ${row}, column ${column}`;
  const name = face === null
    ? `${position}, closed`
    : `${position}, ${face.accessibleName}, ${stateName}`;
  const blocked = paused || matched || game.selection.kind === SELECTION_KINDS.mismatch;

  return (
    <button
      aria-label={name}
      aria-disabled={blocked}
      className={`card-button ${revealed ? "card-button--face" : "card-button--back"}${matched ? " card-button--matched" : ""}`}
      onClick={(event) => handleClick(event, () => onActivate(index))}
      onFocus={() => onFocusCard(index)}
      onKeyDown={(event) => handleKeyDown(event, index, size, onMoveFocus)}
      ref={ref}
      tabIndex={tabStop ? 0 : -1}
      type="button"
    >
      {face === null ? (
        <span aria-hidden="true" className="card-back-mark" />
      ) : (
        <span className="card-face"><Face face={face} /></span>
      )}
      {matched ? <span aria-hidden="true" className="card-check">✓</span> : null}
    </button>
  );
});
.card-button {
  position: relative;
  display: grid;
  place-items: center;
  min-inline-size: 44px;
  inline-size: 100%;
  aspect-ratio: 1;
  padding: 4px;
  border: 2px solid var(--border);
  border-radius: 8px;
  color: var(--text);
  background: var(--back);
  cursor: pointer;
  scroll-margin: 6px;
  transition: border-color 120ms ease;
}

.card-button--face { background: var(--face); }

.card-button:hover:not(.card-button--matched) { border-color: var(--text); }
.card-button--matched,
.card-button--matched:hover { border-color: var(--green); }

.card-button:focus-visible {
  z-index: 1;
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.card-back-mark {
  inline-size: 16px;
  aspect-ratio: 1;
  border: 2px solid var(--border);
  border-radius: 3px;
  transform: rotate(45deg);
}

.card-check {
  position: absolute;
  inset-inline-end: 4px;
  inset-block-end: 0;
  color: var(--green);
  font-size: 18px;
  font-weight: 700;
  line-height: 20px;
}

@media (prefers-reduced-motion: reduce) {
  .card-button { transition: none; }
}
.board-scroll {
  max-inline-size: 100%;
  max-block-size: min(768px, 70dvh);
  overflow: auto;
  padding: 6px;
  border-radius: 12px;
  background: var(--panel);
  overscroll-behavior: contain;
}

.board-grid {
  display: grid;
  gap: 6px;
  inline-size: 100%;
  margin-inline: auto;
}
import type { FaceData } from "./face-data.ts";

const FACE_BACKGROUND = "#111625";

function Shape({ face }: { readonly face: FaceData }) {
  const fill = face.fill === "solid" ? face.color : "none";
  const stroke = face.fill === "outline" ? face.color : "none";
  const strokeWidth = face.fill === "outline" ? 5 : 0;
  const common = { fill, stroke, strokeWidth, strokeLinejoin: "round" as const };

  if (face.shape === "circle") return <circle cx="50" cy="50" r="25" {...common} />;
  if (face.shape === "square") return <rect x="25" y="25" width="50" height="50" {...common} />;
  if (face.shape === "triangle") return <polygon points="50,25 75,75 25,75" {...common} />;
  if (face.shape === "diamond") return <polygon points="50,25 75,50 50,75 25,50" {...common} />;
  if (face.shape === "star") {
    return <polygon points="50,25 56,42 75,42 60,53 66,72 50,61 34,72 40,53 25,42 44,42" {...common} />;
  }
  if (face.shape === "hexagon") {
    return <polygon points="50,25 72,37.5 72,62.5 50,75 28,62.5 28,37.5" {...common} />;
  }
  if (face.shape === "plus") {
    return <path d="M42 25h16v17h17v16H58v17H42V58H25V42h17z" {...common} />;
  }
  return <path d="M25 25h22l28 25-28 25H25l28-25z" {...common} />;
}

export function Face({ face }: { readonly face: FaceData }) {
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 100">
      <Shape face={face} />
      <circle
        cx={face.markerX}
        cy={face.markerY}
        r="5"
        fill={face.color}
        stroke={FACE_BACKGROUND}
        strokeWidth="3"
      />
    </svg>
  );
}
.card-face {
  display: block;
  inline-size: 78%;
  block-size: 78%;
}

.card-face svg {
  display: block;
  inline-size: 100%;
  block-size: 100%;
}

