import { createElement } from "react";
import { renderToStaticMarkup } from "react-dom/server";
import { expect, test } from "@playwright/test";
import { Face } from "../../src/game/board/Face.tsx";
import { getFaceData } from "../../src/game/board/face-data.ts";
import { saveScreenshot } from "./helpers/evidence.ts";

function sheetMarkup(): string {
  const cells: string[] = [];
  for (let id = 0; id < 128; id += 1) {
    const face = getFaceData(id);
    if (face === null) throw new Error(`Missing face ${id}.`);
    cells.push(
      `<div class="face-cell" aria-label="${face.accessibleName}">${renderToStaticMarkup(
        createElement(Face, { face }),
      )}</div>`,
    );
  }

  return `<!doctype html><html lang="en"><meta charset="utf-8"><title>Neon Pairs grayscale face sheet</title>
    <style>body{margin:8px;background:#fff}.face-sheet{display:grid;grid-template-columns:repeat(16,44px);gap:4px}
      .face-cell{width:44px;height:44px;display:grid;place-items:center;background:#111625;border:1px solid #757c9a}
      svg{display:block;width:40px;height:40px;filter:grayscale(1)}</style>
    <main class="face-sheet">${cells.join("")}</main></html>`;
}

test("render the 128 documented face identities as a 44px grayscale sheet", async ({ page }) => {
  await page.setContent(sheetMarkup());
  await expect(page.locator(".face-cell")).toHaveCount(128);
  await saveScreenshot(page, "faces-grayscale-44px.png");
});
import { createGame } from "../../../src/game/create.ts";
import { activateCard } from "../../../src/game/transition.ts";
import { encodeSnapshot } from "../../../src/game/snapshot.ts";
import type { Page } from "@playwright/test";

export type PositionPair = readonly [number, number];

export function pairsForCode(boardCode: string): readonly PositionPair[] {
  const game = createGame(boardCode);
  if (game === null) throw new Error(`Invalid test board: ${boardCode}`);
  const waiting = new Map<number, number>();
  const pairs: PositionPair[] = [];
  game.board.deck.forEach((face, index) => {
    const first = waiting.get(face);
    if (first === undefined) waiting.set(face, index);
    else {
      waiting.delete(face);
      pairs.push([first, index]);
    }
  });
  return pairs;
}

export function completedSnapshot(boardCode: string): string {
  const game = createGame(boardCode);
  if (game === null) throw new Error(`Invalid test board: ${boardCode}`);
  let state = game;
  for (const [first, second] of pairsForCode(boardCode)) {
    state = activateCard(activateCard(state, first), second);
  }
  return encodeSnapshot(state);
}

export async function loadBoard(page: Page, boardCode: string): Promise<void> {
  await page.getByText("Reproduce a game", { exact: true }).click();
  await page.getByLabel("Board code").fill(boardCode);
  await page.getByRole("button", { name: "Load board", exact: true }).click();
}

export function cardAt(page: Page, index: number) {
