import { expect, test } from "@playwright/test";
import { cardAt, loadBoard, pairsForCode, solveWithPointer } from "./helpers/game.ts";
import { freezePageTime } from "./helpers/board.ts";

for (const size of [4, 6, 8, 10, 12, 14, 16]) {
