import { BOARD_SIZES, isBoardSize, type BoardSize } from "../board/sizes.ts";
import { createGame } from "../create.ts";
import { advanceGame, formatElapsedTime } from "../clock.ts";
import { decodeSnapshot, encodeSnapshot } from "../snapshot.ts";
import { activateCard } from "../transition.ts";
import { isWon, pairCount, type GameState } from "../state.ts";
import {
  browserStorage,
  emptyPreferences,
  readPreferences,
  writePreferences,
  type StorageLike,
  type StoredPreferences,
} from "./storage.ts";

const MAX_SEED = 2147483646;

export interface SessionAnnouncement {
  readonly id: number;
  readonly text: string;
}

export interface GameSessionView {
  readonly game: GameState;
  readonly size: BoardSize;
  readonly bestMoves: number | null;
  readonly dealRevision: number;
  readonly paused: boolean;
  readonly visible: boolean;
  readonly running: boolean;
  readonly pairCount: number;
  readonly totalPairs: number;
  readonly won: boolean;
  readonly celebrationId: number;
  readonly announcement: SessionAnnouncement | null;
  readonly status: string;
}

export interface SessionOptions {
  readonly now?: () => number;
  readonly storage?: StorageLike | null;
  readonly seedSource?: () => number;
}

function randomSeed(): number {
  try {
    const values = new Uint32Array(1);
    globalThis.crypto.getRandomValues(values);
    const value = values[0];
    if (value !== undefined) return (value % MAX_SEED) + 1;
  } catch {
    // Some file origins do not expose Web Crypto.
  }
  return Math.floor(Math.random() * MAX_SEED) + 1;
}

function boardCode(size: BoardSize, source: () => number, previous?: string): string {
  let seed = Math.floor(source());
  if (!Number.isFinite(seed) || seed < 1 || seed > MAX_SEED) seed = randomSeed();
  const priorSeed = previous?.split("-")[2];
  if (String(seed) === priorSeed) seed = seed === MAX_SEED ? 1 : seed + 1;
  return `np1-${size}-${seed}`;
}

function gameFor(code: string): GameState {
  const game = createGame(code);
  if (game === null) throw new Error("Generated a board code that is not valid.");
  return game;
}

function startNow(clock: (() => number) | undefined): number {
  const value = clock?.() ?? performance.now();
  return Number.isFinite(value) ? value : 0;
}

export class GameSession {
  private readonly clock: () => number;
  private readonly seedSource: () => number;
  private readonly storage: StorageLike | undefined;
  private preferences: StoredPreferences;
  private game: GameState;
  private paused = false;
  private visible = true;
  private dealRevision = 0;
  private celebrationId = 0;
  private announcementId = 0;
  private announcement: SessionAnnouncement | null = null;
  private status = "";
  private lastNow: number;
  private fractionalMs = 0;
  private view: GameSessionView;
  private readonly listeners = new Set<(view: GameSessionView) => void>();

  public constructor(options: SessionOptions = {}) {
    this.clock = options.now ?? (() => performance.now());
    this.seedSource = options.seedSource ?? randomSeed;
    this.storage = options.storage === null
      ? undefined
      : options.storage ?? browserStorage();
    this.preferences = this.storage === undefined
