import { formatElapsedTime } from "../clock.ts";
import { isWon, pairCount, type GameState } from "../state.ts";

export interface TurnResult {
  readonly message: string;
  readonly won: boolean;
}

export function describeTurn(before: GameState, after: GameState): TurnResult | null {
  if (after.matched.length > before.matched.length) {
    if (isWon(after)) {
      return {
        message: `Pair found. All pairs found in ${after.moves} moves and ${formatElapsedTime(after.elapsedMs)}.`,
        won: true,
      };
    }
    const pairs = pairCount(after);
    const noun = pairs === 1 ? "pair" : "pairs";
    return { message: `Pair found. ${pairs} ${noun} matched.`, won: false };
  }
  return after.selection.kind === "mismatch"
    ? { message: "No match. Cards close after a short pause.", won: false }
    : null;
}
import {
  CLOSED_SELECTION,
  SELECTION_KINDS,
  isWon,
  type GameState,
} from "./state.ts";

export const MAX_ELAPSED_MS = 359999999;
export const MISMATCH_DURATION_MS = 800;

export function formatElapsedTime(elapsedMs: number): string {
  const minutes = Math.floor(elapsedMs / 60000);
  const seconds = Math.floor((elapsedMs % 60000) / 1000);
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (
    !Number.isSafeInteger(milliseconds) ||
    milliseconds <= 0 ||
    !state.started ||
    isWon(state)
  ) {
    return state;
  }

  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  const selection = state.selection;

  if (selection.kind !== SELECTION_KINDS.mismatch) {
    return Object.freeze({ ...state, elapsedMs });
  }

  if (milliseconds >= selection.remainingMs) {
    return Object.freeze({ ...state, elapsedMs, selection: CLOSED_SELECTION });
  }

  return Object.freeze({
    ...state,
    elapsedMs,
    selection: Object.freeze({
      ...selection,
      remainingMs: selection.remainingMs - milliseconds,
    }),
  });
}
import { forwardRef, useImperativeHandle, useRef, useState, type CSSProperties } from "react";
import type { GameState } from "../state.ts";
import { Card } from "./Card.tsx";
import "./Board.css";

export interface BoardProps {
  readonly game: GameState;
  readonly paused: boolean;
  readonly onActivate: (index: number) => void;
}

export interface BoardHandle {
  focusRememberedCard(): void;
}

export const Board = forwardRef<BoardHandle, BoardProps>(function Board(
  { game, paused, onActivate },
  ref,
) {
  const rememberedIndex = useRef(0);
  const [tabStop, setTabStop] = useState(0);
  const cardRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const size = game.board.size;
  const count = game.board.deck.length;
  const style: CSSProperties = {
    gridTemplateColumns: `repeat(${size}, minmax(44px, 1fr))`,
    minWidth: `${size * 44 + (size - 1) * 6}px`,
    maxWidth: `${size * 88 + (size - 1) * 6}px`,
  };

  useImperativeHandle(ref, () => ({
    focusRememberedCard: () => {
      const target = cardRefs.current[rememberedIndex.current] ?? cardRefs.current[0];
      target?.focus();
    },
  }), []);

  function moveFocus(index: number): void {
    cardRefs.current[index]?.focus();
  }

  function rememberFocus(index: number): void {
    rememberedIndex.current = index;
    setTabStop(index);
    cardRefs.current[index]?.scrollIntoView({ block: "nearest", inline: "nearest" });
  }

  return (
    <div className="board-scroll">
      <div className="board-grid" aria-label={`Card board, ${size} by ${size}`} role="group" style={style}>
        {Array.from({ length: count }, (_, index) => (
          <Card
            key={index}
            ref={(node) => { if (node !== null) cardRefs.current[index] = node; }}
            game={game}
            index={index}
            onActivate={onActivate}
            onFocusCard={rememberFocus}
            onMoveFocus={moveFocus}
            paused={paused}
            tabStop={index === tabStop}
          />
        ))}
      </div>
    </div>
  );
});
import { forwardRef, type KeyboardEvent, type MouseEvent } from "react";
import { SELECTION_KINDS, type GameState } from "../state.ts";
import { Face } from "./Face.tsx";
import { getFaceData } from "./face-data.ts";
import { focusDestination, type ArrowDirection } from "./navigation.ts";
import "./Face.css";
import "./Card.css";

export interface CardProps {
  readonly game: GameState;
  readonly index: number;
  readonly tabStop: boolean;
  readonly paused: boolean;
  readonly onActivate: (index: number) => void;
  readonly onFocusCard: (index: number) => void;
  readonly onMoveFocus: (index: number) => void;
}

function isMatched(game: GameState, index: number): boolean {
  return game.matched.includes(index);
}

function isRevealed(game: GameState, index: number, matched: boolean): boolean {
  if (matched) return true;
  if (game.selection.kind === SELECTION_KINDS.one) return game.selection.index === index;
  return game.selection.kind === SELECTION_KINDS.mismatch &&
    (game.selection.first === index || game.selection.second === index);
}

function handleClick(event: MouseEvent<HTMLButtonElement>, activate: () => void): void {
  if (
    event.button !== 0 ||
    event.altKey || event.ctrlKey || event.metaKey || event.shiftKey
  ) {
    return;
  }
  activate();
}

function isArrowDirection(key: string): key is ArrowDirection {
  return key === "ArrowLeft" || key === "ArrowRight" || key === "ArrowUp" || key === "ArrowDown";
}

function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number, size: number, move: (index: number) => void): void {
  if (event.altKey || event.ctrlKey || event.metaKey || event.shiftKey) return;
  if (!isArrowDirection(event.key)) return;
  event.preventDefault();
  move(focusDestination(index, size, event.key));
}

export const Card = forwardRef<HTMLButtonElement, CardProps>(function Card({
  game,
  index,
  tabStop,
  paused,
  onActivate,
  onFocusCard,
  onMoveFocus,
}, ref) {
  const size = game.board.size;
  const matched = isMatched(game, index);
  const revealed = isRevealed(game, index, matched);
  const faceId = revealed ? game.board.deck[index] : undefined;
  const face = faceId === undefined ? null : getFaceData(faceId);
  const row = Math.floor(index / size) + 1;
  const column = (index % size) + 1;
  const stateName = matched ? "matched" : revealed ? "revealed" : "closed";
  const position = `Row ${row}, column ${column}`;
  const name = face === null
    ? `${position}, closed`
    : `${position}, ${face.accessibleName}, ${stateName}`;
  const blocked = paused || matched || game.selection.kind === SELECTION_KINDS.mismatch;

  return (
    <button
      aria-label={name}
      aria-disabled={blocked}
      className={`card-button ${revealed ? "card-button--face" : "card-button--back"}${matched ? " card-button--matched" : ""}`}
      onClick={(event) => handleClick(event, () => onActivate(index))}
      onFocus={() => onFocusCard(index)}
      onKeyDown={(event) => handleKeyDown(event, index, size, onMoveFocus)}
      ref={ref}
      tabIndex={tabStop ? 0 : -1}
      type="button"
    >
      {face === null ? (
        <span aria-hidden="true" className="card-back-mark" />
      ) : (
        <span className="card-face"><Face face={face} /></span>
      )}
      {matched ? <span aria-hidden="true" className="card-check">✓</span> : null}
    </button>
  );
});
