  if (face.shape === "diamond") return <polygon points="50,25 75,50 50,75 25,50" {...common} />;
  if (face.shape === "star") {
    return <polygon points="50,25 56,42 75,42 60,53 66,72 50,61 34,72 40,53 25,42 44,42" {...common} />;
  }
  if (face.shape === "hexagon") {
    return <polygon points="50,25 72,37.5 72,62.5 50,75 28,62.5 28,37.5" {...common} />;
  }
  if (face.shape === "plus") {
    return <path d="M42 25h16v17h17v16H58v17H42V58H25V42h17z" {...common} />;
  }
  return <path d="M25 25h22l28 25-28 25H25l28-25z" {...common} />;
}

export function Face({ face }: { readonly face: FaceData }) {
  return (
    <svg aria-hidden="true" focusable="false" viewBox="0 0 100 100">
      <Shape face={face} />
      <circle
        cx={face.markerX}
        cy={face.markerY}
        r="5"
        fill={face.color}
        stroke={FACE_BACKGROUND}
        strokeWidth="3"
      />
    </svg>
  );
}
export const SHAPES = [
  "circle",
  "square",
  "triangle",
  "diamond",
  "star",
  "hexagon",
  "plus",
  "chevron",
] as const;

export const MARKERS = [
  "top",
  "top-right",
  "right",
  "bottom-right",
  "bottom",
  "bottom-left",
  "left",
  "top-left",
] as const;

export const PALETTE = [
  { name: "cyan", color: "#63E7FF" },
  { name: "magenta", color: "#FF71D6" },
  { name: "green", color: "#8BEA7D" },
  { name: "yellow", color: "#FFE082" },
  { name: "orange", color: "#FFB064" },
  { name: "violet", color: "#B49AFF" },
  { name: "rose", color: "#FF8296" },
  { name: "ice", color: "#D9F3FF" },
] as const;

export interface FaceData {
  readonly id: number;
  readonly shape: (typeof SHAPES)[number];
  readonly marker: (typeof MARKERS)[number];
  readonly fill: "solid" | "outline";
  readonly paletteName: (typeof PALETTE)[number]["name"];
  readonly color: string;
  readonly markerX: number;
  readonly markerY: number;
  readonly accessibleName: string;
}

const MARKER_POINTS: readonly (readonly [number, number])[] = [
  [50, 10],
  [78.284, 21.716],
  [90, 50],
  [78.284, 78.284],
  [50, 90],
  [21.716, 78.284],
  [10, 50],
  [21.716, 21.716],
];

export function getFaceData(id: number): FaceData | null {
  if (!Number.isSafeInteger(id) || id < 0 || id > 127) return null;
  const shape = SHAPES[id % SHAPES.length];
  const markerIndex = Math.floor(id / 8) % MARKERS.length;
  const marker = MARKERS[markerIndex];
  const palette = PALETTE[markerIndex];
  const point = MARKER_POINTS[markerIndex];
  if (shape === undefined || marker === undefined || palette === undefined || point === undefined) {
    return null;
  }
  const fill = id < 64 ? "solid" : "outline";
  return {
    id,
    shape,
    marker,
    fill,
    paletteName: palette.name,
    color: palette.color,
    markerX: point[0],
    markerY: point[1],
    accessibleName: `${palette.name} ${fill} ${shape}, marker ${marker}`,
  };
}
import { useEffect, useMemo, useRef, useSyncExternalStore } from "react";
import { GameSession } from "./session.ts";
import type { GameSessionView } from "./types.ts";

export interface GameSessionActions {
  readonly activateCard: (index: number) => void;
  readonly changeSize: (size: number) => void;
  readonly exportSnapshot: () => string;
  readonly loadBoard: (draft: string) => void;
  readonly loadSnapshot: (text: string) => void;
  readonly newGame: () => void;
  readonly restart: () => void;
  readonly resume: () => void;
}

export type GameSessionApi = GameSessionView & GameSessionActions;

function browserStorage() {
  try {
    return window.localStorage;
  } catch {
    return null;
  }
}

export function useGameSession(): GameSessionApi {
  const reference = useRef<GameSession | null>(null);
  if (reference.current === null) {
    reference.current = new GameSession({ storage: browserStorage() });
  }
  const session = reference.current;
  const view = useSyncExternalStore(
    session.subscribe,
    session.getSnapshot,
    session.getSnapshot,
  );

  useEffect(() => {
    const updateVisibility = (): void => {
      session.setVisible(document.visibilityState !== "hidden", performance.now());
    };
    updateVisibility();
    document.addEventListener("visibilitychange", updateVisibility);
    return () => document.removeEventListener("visibilitychange", updateVisibility);
  }, [session]);

  useEffect(() => {
    if (!view.running) return undefined;
    const revision = view.dealRevision;
    let active = true;
    let frame = 0;
    const update = (timestamp: number): void => {
      if (!active || session.getSnapshot().dealRevision !== revision) return;
      session.tick(timestamp);
      if (session.shouldTick()) frame = requestAnimationFrame(update);
    };
    frame = requestAnimationFrame(update);
    return () => {
      active = false;
      cancelAnimationFrame(frame);
    };
  }, [session, view.dealRevision, view.running]);

  const actions = useMemo<GameSessionActions>(() => ({
    activateCard: (index) => session.activateCard(index),
    changeSize: (size) => session.changeSize(size),
    exportSnapshot: () => session.exportSnapshot(),
    loadBoard: (draft) => session.loadBoard(draft),
    loadSnapshot: (text) => session.loadSnapshot(text),
    newGame: () => session.newGame(),
    restart: () => session.restart(),
    resume: () => session.resume(),
  }), [session]);

  return { ...view, ...actions };
}

