import { describe, expect, it } from "vitest";
import { createGame } from "./create.ts";
import { advanceGame, formatElapsedTime } from "./clock.ts";
import { activateCard } from "./transition.ts";
import { isWon } from "./state.ts";

function game() {
  const state = createGame("np1-4-1");
  if (state === null) throw new Error("Test board should be valid.");
  return state;
}

describe("card transitions", () => {
  it("formats elapsed minutes without wrapping after an hour", () => {
    expect(formatElapsedTime(3600000)).toBe("60:00");
    expect(formatElapsedTime(59999)).toBe("0:59");
  });

  it("ignores repeating the first card and counts only the second activation", () => {
    const initial = game();
    const first = activateCard(initial, 0);
    expect(activateCard(first, 0)).toBe(first);
    expect(first.moves).toBe(0);
    expect(activateCard(first, 11).moves).toBe(1);
  });

  it("matches immediately and preserves the match after later turns", () => {
    const first = activateCard(game(), 0);
    const match = activateCard(first, 11);
    expect(match.matched).toEqual([0, 11]);
    expect(match.selection.kind).toBe("closed");
    expect(match.moves).toBe(1);
    expect(isWon(match)).toBe(false);
  });

  it("blocks mismatch activations and closes exactly at 800 active ms", () => {
    const first = activateCard(game(), 1);
    const miss = activateCard(first, 2);
    expect(miss.selection).toEqual({ kind: "mismatch", first: 1, second: 2, remainingMs: 800 });
    expect(activateCard(miss, 0)).toBe(miss);
    const waiting = advanceGame(miss, 799);
    expect(waiting.selection).toEqual({ kind: "mismatch", first: 1, second: 2, remainingMs: 1 });
    expect(advanceGame(waiting, 1).selection.kind).toBe("closed");
  });

  it("caps elapsed time and keeps it stopped after a win", () => {
    const nearCap = {
      ...activateCard(game(), 0),
      elapsedMs: 359999998,
    };
    const capped = advanceGame(nearCap, 10);
    expect(capped.elapsedMs).toBe(359999999);
    expect(advanceGame(capped, 10).elapsedMs).toBe(359999999);
  });
});
import {
  CLOSED_SELECTION,
  SELECTION_KINDS,
  isWon,
  type GameState,
} from "./state.ts";
import { MISMATCH_DURATION_MS } from "./clock.ts";

export const MAX_MOVES = 999999;

function isMatched(state: GameState, index: number): boolean {
  return state.matched.includes(index);
}

export function activateCard(state: GameState, index: number): GameState {
  if (
    !Number.isSafeInteger(index) ||
    index < 0 ||
    index >= state.board.deck.length ||
    isWon(state) ||
    isMatched(state, index)
  ) {
    return state;
  }

  const selection = state.selection;
  if (selection.kind === SELECTION_KINDS.mismatch) return state;

  if (selection.kind === SELECTION_KINDS.closed) {
    return Object.freeze({
      ...state,
      selection: Object.freeze({ kind: SELECTION_KINDS.one, index }),
      started: true,
    });
  }

  if (selection.index === index) return state;

  const moves = Math.min(MAX_MOVES, state.moves + 1);
  const firstFace = state.board.deck[selection.index];
  const secondFace = state.board.deck[index];

  if (firstFace === secondFace) {
    return Object.freeze({
      ...state,
      matched: Object.freeze([...state.matched, selection.index, index]),
      selection: CLOSED_SELECTION,
      moves,
    });
  }

  return Object.freeze({
    ...state,
    selection: Object.freeze({
      kind: SELECTION_KINDS.mismatch,
      first: selection.index,
      second: index,
      remainingMs: MISMATCH_DURATION_MS,
    }),
    moves,
  });
}
import type { BoardCode } from "./board/code.ts";
import { generateDeck } from "./board/generate.ts";
import type { BoardSize } from "./board/sizes.ts";

export const SELECTION_KINDS = {
  closed: "closed",
  one: "one",
  mismatch: "mismatch",
} as const;

export interface ClosedSelection {
  readonly kind: typeof SELECTION_KINDS.closed;
}

export interface OneSelection {
  readonly kind: typeof SELECTION_KINDS.one;
  readonly index: number;
}

export interface MismatchSelection {
  readonly kind: typeof SELECTION_KINDS.mismatch;
  readonly first: number;
  readonly second: number;
  readonly remainingMs: number;
}

export type GameSelection = ClosedSelection | OneSelection | MismatchSelection;

export interface GameBoard {
  readonly code: string;
  readonly size: BoardSize;
  readonly deck: readonly number[];
}

export interface GameState {
  readonly board: GameBoard;
  readonly matched: readonly number[];
  readonly selection: GameSelection;
  readonly moves: number;
  readonly elapsedMs: number;
  readonly started: boolean;
}

export const CLOSED_SELECTION: ClosedSelection = Object.freeze({
  kind: SELECTION_KINDS.closed,
});

export function createGameFromCode(board: BoardCode): GameState {
  const gameBoard: GameBoard = Object.freeze({
    code: board.value,
    size: board.size,
    deck: generateDeck(board),
  });

  return Object.freeze({
    board: gameBoard,
    matched: Object.freeze([]),
    selection: CLOSED_SELECTION,
    moves: 0,
    elapsedMs: 0,
    started: false,
  });
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

