/work/tests/e2e/touch-scroll.spec.ts.content:
import { expect, test } from "@playwright/test";
import { cardAt } from "./helpers/game.ts";

test("scroll a large mobile board and activate its first and last cards by touch", async ({ browser }) => {
  const context = await browser.newContext({
    viewport: { width: 360, height: 800 },
    deviceScaleFactor: 1,
    hasTouch: true,
    isMobile: true,
  });
  const page = await context.newPage();
  await page.goto("http://127.0.0.1:4173");
  await page.getByLabel("Grid size").selectOption("16");
  await expect(page.locator(".card-button")).toHaveCount(256);

  const session = await context.newCDPSession(page);
  await session.send("Input.synthesizeScrollGesture", {
    x: 160,
    y: 500,
    xDistance: -500,
    yDistance: -400,
    gestureSourceType: "touch",
    speed: 1000,
  });
  const scrolled = await page.locator(".board-scroll").evaluate((element) => ({
    left: element.scrollLeft,
    top: element.scrollTop,
  }));
  expect(scrolled.left).toBeGreaterThan(0);
  expect(scrolled.top).toBeGreaterThan(0);

  await cardAt(page, 0).tap();
  await expect(cardAt(page, 0)).toHaveAttribute("aria-label", /revealed$/);
  await cardAt(page, 255).tap();
  await expect(cardAt(page, 255)).toHaveAttribute("aria-label", /revealed$/);
  await session.detach();
  await context.close();
});

